SELECT * FROM (SELECT DATE_TRUNC('MONTH', order_date) order_month, CASE WHEN YEAR(order_date) < 2024 THEN 'before_2024' WHEN YEAR(order_date) = 2024 THEN '2024' ELSE 'after_2024' END order_cohort, ROUND(AVG(discount), 2) avg_discount, MIN(shipping_fee) min_shipping_fee FROM orders WHERE order_date >= '2024-04-01' GROUP BY DATE_TRUNC('MONTH', order_date), CASE WHEN YEAR(order_date) < 2024 THEN 'before_2024' WHEN YEAR(order_date) = 2024 THEN '2024' ELSE 'after_2024' END) t WHERE avg_discount > 60 ORDER BY avg_discount DESC, order_month, order_cohort LIMIT 5
